26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
28	
29	const BASE_PREMIUMS: Record<string, number> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
39	
40	const BLOCK_SIZE = 3;
41	const BLOCK_BASE_PREMIUM = 60;
42	
43	const alikeItemGroups = (items: Item[]): Item[][] => [
44	  ...items
45	    .reduce(
46	      (groupsByType, item) =>
47	        groupsByType.set(item.type, [
48	          ...(groupsByType.get(item.type) ?? []),
49	          item,
50	        ]),
51	      new Map<string, Item[]>(),
52	    )
53	    .values(),
54	];
55	
56	const basePremiumOfGroup = (group: Item[]): number =>
57	  group.length === BLOCK_SIZE
58	    ? BLOCK_BASE_PREMIUM
59	    : group.reduce((total, item) => total + basePremiumOf(item), 0);
60	
61	const totalBasePremiumOf = (items: Item[]): number =>
62	  alikeItemGroups(items).reduce(
63	    (total, group) => total + basePremiumOfGroup(group),
64	    0,
65	  );
66	
67	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
68	
69	type ItemSurchargeRule = {
70	  appliesTo: (item: Item) => boolean;
71	  rate: number;
72	};
73	
74	const CURSE_SURCHARGE_RATE = 0.5;
75	const HIGH_ENCHANTMENT_THRESHOLD = 5;
76	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
77	
78	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
79	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
80	  {
81	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
82	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
83	  },
84	];
85	
86	const totalSurchargeRateOf = (item: Item): number =>
87	  ITEM_SURCHARGE_RULES.reduce(
88	    (rate, rule) => (rule.appliesTo(item) ? rate + rule.rate : rate),
89	    0,
90	  );
91	
92	const itemSurchargeOf = (item: Item): number =>
93	  basePremiumOf(item) * totalSurchargeRateOf(item);
94	
95	const totalItemSurchargeOf = (items: Item[]): number =>
96	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
97	
98	const LOYALTY_YEARS_THRESHOLD = 2;
99	const LOYALTY_DISCOUNT_RATE = -0.2;
100	
101	type PolicyModifierRule = {
102	  appliesTo: (customer: Customer) => boolean;
103	  rate: number;
104	};
105	
106	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
107	  {
108	    appliesTo: (customer) =>
109	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
110	    rate: LOYALTY_DISCOUNT_RATE,
111	  },
112	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
113	];
114	
115	const totalPolicyModifierRateOf = (customer: Customer): number =>
116	  POLICY_MODIFIER_RULES.reduce(
117	    (rate, rule) => (rule.appliesTo(customer) ? rate + rule.rate : rate),
118	    0,
119	  );
120	
121	const quotePremium = (items: Item[], customer: Customer): number => {
122	  const basePremium = totalBasePremiumOf(items);
123	
124	  return roundedInMHPCOsFavour(
125	    basePremium +
126	      totalItemSurchargeOf(items) +
127	      basePremium * totalPolicyModifierRateOf(customer) +
128	      PROCESSING_FEE,
129	  );
130	};
131	
132	export const runScenario = (scenario: Scenario): ScenarioResult => ({
133	  results: scenario.steps.map((step) => ({
134	    premium: quotePremium(step.items, scenario.customer),
135	  })),
136	});
